Te = 1/50;
k=2;
wn=5;
theta=0.7;
num = [k*wn^2] %[output:3bf83e90]
den = [1 2*theta*wn wn^2] %[output:65e5cebb]

[numd, dend] = c2dm(num, den, Te, 'zoh');
tfd1 = tf(numd, dend, Te) %[output:2426991d]
[numd, dend] = c2dm(num, den, Te, 'foh');
tfd2 = tf(numd, dend, Te) %[output:94006ff5]
[numd, dend] = c2dm(num, den, Te, 'tustin');
tfd3 = tf(numd, dend, Te) %[output:5dd77439]
[numd, dend] = c2dm(num, den, Te, 'matched');
tfd4 = tf(numd, dend, Te) %[output:9cbe564f]

zplane(numd, dend) %[output:05cedf12]

